INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('148727c4-15a0-4fca-92f2-d53aaf1868df', 'emailEnabledAccountBodyHtml', '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ru Бизнес» разблокирована.</p><p>Логин: <a class="no_block" href="{0}">{0}</a></p>', null, 'user', 'Сообщение о блокировке', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('17d329be-985d-49ab-a75c-0377448b3eb7', 'emailVerificationLoginBodyHtml', '<p>Подтвердите Вашу учетную запись для входа в Личный кабинет «Дом.ru Бизнес» по ссылке.</p><p><a href="{0}">Подтвердить учетную запись</a></p><p>Эта ссылка устареет через {4}.</p>', null, 'user', 'Сообщение о подтверждение УЗ', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('2bcb24f5-6168-4809-ac79-a681c08e33e9', 'identityProviderLinkBodyHtml', '<p>Был создан запрос на связь Вашей учетной записи <a class="no_block" href="mailto:{1}">{1}</a> с учетной записью пользователя {2} {0}. После объединения учетных записей Вы можете войти в Личный кабинет «Дом.ru Бизнес» <a class="no_block" href="mailto:{1}">{1}</a> через {0}. Если это были Вы, пройдите по ссылке, чтобы связать учетные записи.</p><p><a href="{3}">Связать учетные записи</a></p><p>Эта ссылка устареет через 24 часа.</p><p class="content__additional">Если Вы не хотите объединять учетные записи, проигнорируйте это письмо.</p>', null, 'user', 'Сообщение о связывании УЗ', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('2c03c1ab-b921-416f-ba16-4f4ba0024ce7', 'emailVerificationAuthBodyHtml', '<p>Код для подтверждения данных Вашей учетной записи Личного кабинета «Дом.ru Бизнес»: {0}</p>', null, 'user', 'Сообщение о подтверждении УЗ', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('3aa0c9ae-52ea-4786-880b-14e8392786e1', 'emailVerificationBodyHtml', '<p>Была создана учетная запись <a class="no_block" href="mailto:{2}">{2}</a>. Если это были Вы, пройдите по ссылке для подтверждения вашего email.</p><p><a href="{0}">Подтвердить E-mail</a></p><p>Эта ссылка устареет через {4}.</p><p class="content__additional">Если Вы не создавали учетную запись, просто проигнорируйте это письмо.</p>', null, 'user', 'Сообщение о создании УЗ и подтверждение', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('4311bdd8-b4e0-472e-82cb-604b74a99951', 'emailCredentialDisableBodyHtml', '<p>Чтобы защитить Ваши персональные данные, пароль к учетной записи для входа в Личный кабинет «Дом.ru Бизнес» был сброшен. Чтобы активировать учетную запись перейдите по ссылке <a href="{0}">«Восстановление пароля»</a> и смените его.</p>', null, 'user', 'Сообщение о сбросе пароля', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('4a3df31f-27de-447b-95cd-1768d4efe263', 'emailDisabledAccountBodyHtml', '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ru Бизнес» заблокирована. Чтобы снять блокировку, обратитесь в службу технической поддержки «Дом.ru Бизнес» в чате на сайте <a class="no_block" href="https://newlkb2b.dom.ru">https://newlkb2b.dom.ru</a>, или по телефону <a class="no_block" href="tel:88003339000">88003339000</a>.</p>', null, 'user', 'Сообщение о блокировке УЗ', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('743e43aa-d84c-48cc-a3c2-9f874fde4532', 'emailAccountDataBodyHtml', '<p>Для Вас создана учетная запись для входа в Личный кабинет «Дом.ru Бизнес».</p><p>Логин: <a class="no_block" href="{0}">{0}</a></p><p>Перейдите по ссылке и установите пароль.</p>', null, 'user', 'Сообщение о создании УЗ', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('794ef420-a23f-4da0-a994-508a3ab6e968', 'emailSendLoginBodyHtml', '<p>Для авторизации в <a class="no_block" href="https://newlkb2b.dom.ru">Личном кабинете</a> необходимо указать логин и пароль, установленный вами при регистрации личного кабинета.</p>', null, 'user', 'Сообщение для авторизации', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('9f558134-412b-11ec-973a-0242ac130003', 'emailAccountCreateBodyHtml', '<p>Для Вас создана учетная запись для входа в Личный кабинет «Дом.ru Бизнес».</p><p>Логин: <a class="no_block" href="{0}">{0}</a></p>', null, 'user', 'Сообщение о создании УЗ', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('bcdf6831-85f5-4643-9bd9-afb9a873777e', 'emailResetPasswordBodyHtml', '<p>Пароль вашей учетной записи был сброшен.</p><p>Установите новый пароль по <a class="no_block" href="{0}">ссылке</a>, чтобы завершить процесс и восстановить доступ к личному кабинету. Срок действия ссылки 12 часов.</p>', null, 'user', 'Сообщение о сбросе пароля', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('be81db8c-350b-4abc-96cc-90032ad9b22c', 'emailLoginAndPhoneHtml', '<p>Ваш логин:<br><b>{0}</b><br>или<br><b>{1}</b></p>', null, 'user', 'Сообщение отправки логина и телефона', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('deeec109-9620-4f7b-9063-cfd44d682353', 'passwordResetBodyHtml', '<p>Был создан запрос на изменение пароля от Вашей учетной записи {2}. Если это были Вы, пройдите по ссылке</p><p><a href="{0}">Изменить пароль</a></p><p>Эта ссылка устареет через  {1} минут.</p><p class="content__additional">Если Вы не хотите сбрасывать пароль, просто проигнорируйте это письмо и ничего не изменится.</p>', null, 'user', 'Сообщение запрос на измения пароля', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('e49616d7-efbf-4f9e-a0a4-8fef8922dc3c', 'emailLoginHtml', '<p>Ваш логин:<br><b>{0}</b></p>', null, 'user', 'Сообщение об отправке логина', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('f00d4c56-7afd-4aad-8f41-c855ea9b8d67', 'emailPasswordFooterHtml', '<p>Мы не храним ваши пароли.</p><p>Если вы забыли свой пароль или у вас не получается войти в <a class="no_block" href="https://newlkb2b.dom.ru">Личный кабинет</a> - воспользуйтесь формой восстановления пароля по кнопке «Забыли пароль?»</p><p><ul><li>Для восстановления данных укажите ваш логин</li><li>На ваш адрес электронной почты будет отправлена ссылка для восстановления пароля.<br>Срок действия ссылки 5 минут</li></ul></p><br><p><a class="no_block" href="https://newlkb2b.dom.ru">Перейти в Личный кабинет</a></p>', null, 'user', 'Футер сообщения', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('fb0d728d-2e50-4556-9e6e-c8d787225496', 'executeActionsBodyHtml', '<p>Администратор «Дом.ru Бизнес» просит обновить Вас данные учетной записи <a class="no_block" href="mailto:{2}">{2}</a>. Пройдите по ссылке</p><p><a class="no_block" href="{0}">Обновить данные</a>,</p><p>чтобы начать этот процесс.</p><p>Эта ссылка устареет через {5}.</p>', null, 'user', 'Сообщение от администратора для обновления данных', null, 'MESSAGE');

INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('087fe2f4-5a67-11ec-bf63-0242ac130002', 'blockNotificationSchedulerHtml', '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ru Бизнес» заблокирована.</p><p>Чтобы снять блокировку, обратитесь в службу технической поддержки «Дом.ru Бизнес» в чате на сайте <a class="no_block" href="https://newlkb2b.dom.ru">newlkb2b.dom.ru</a> или по телефону <a href="tel:88003339000">88003339000</a>.</p>', null, 'user', 'Сообщение от scheduler о блокировке', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('0f5150ea-5a67-11ec-bf63-0242ac130002', 'blockNotificationSchedulerHtml', '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ru Бизнес» заблокирована.</p><p>Чтобы снять блокировку, обратитесь в службу технической поддержки «Дом.ru Бизнес» в чате на сайте <a class="no_block" href="https://newlkb2b.dom.ru">newlkb2b.dom.ru</a> или по телефону <a href="tel:88003339000">88003339000</a>.</p>', null, 'manager', 'Сообщение от scheduler о блокировке', null, 'MESSAGE');

INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('13449b80-5a67-11ec-bf63-0242ac130002', 'blockPrepareNotificationSchedulerHtml', '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ru Бизнес» будет заблокирована через %s.</p><p>Для предотвращения блокировки учетной записи, просим Вас войти в <a class="no_block" href="%s">Личный кабинет</a> до истечения указанного срока.</p>', null, 'manager', 'Сообщение от scheduler предупреждении о блокировке', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('174d9ccc-5a67-11ec-bf63-0242ac130002', 'blockPrepareNotificationSchedulerHtml', '<p>Ваша учетная запись для входа в Личный кабинет «Дом.ru Бизнес» будет заблокирована через %s.</p><p>Для предотвращения блокировки учетной записи, просим Вас войти в <a class="no_block" href="%s">Личный кабинет</a> до истечения указанного срока.</p>', null, 'user', 'Сообщение от scheduler предупреждении о блокировке', null, 'MESSAGE');

INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('1a4b398e-5a67-11ec-bf63-0242ac130002', 'passwordExpiresSchedulerHtml', '<p>Срок действия пароля от учетной записи для входа в Личный кабинет «Дом.ru Бизнес» истёк. Для восстановления пароля Вам необходимо перейти по <a class="no_block" href="%s">ссылке</a> и воспользоваться функцией «Забыли пароль?»</p>', null, 'user', 'Сообщение от scheduler о истечении срока пароля', null, 'MESSAGE');
INSERT INTO SETTINGS (ID, EXT_ID, VALUE, `DESC`, REALM_ID, NAME, UNIT, TYPE) VALUES ('1d59d0a4-5a67-11ec-bf63-0242ac130002', 'passwordExpiresSchedulerHtml', '<p>Срок действия пароля от учетной записи для входа в Личный кабинет «Дом.ru Бизнес» истёк. Для восстановления пароля Вам необходимо перейти по <a class="no_block" href="%s">ссылке</a> и воспользоваться функцией «Забыли пароль?»</p>', null, 'manager', 'Сообщение от scheduler о истечении срока пароля', null, 'MESSAGE');


